SELECT sku, gtin, name, pack_size, flow, selling_price_inr, cost_inr, case_units
FROM store.products
WHERE name ILIKE '%atta%' AND pack_size ILIKE '%5 kg%';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'products';

